import Foundation
func upload(data:Data) async throws -> Data{
  let b="Boundary-\(UUID().uuidString)"
  var req=URLRequest(url:URL(string:"{{upload_url}}")!);req.httpMethod="POST"
  req.setValue("multipart/form-data; boundary=\(b)",forHTTPHeaderField:"Content-Type")
  var body=Data()
  body.append("--\(b)\r\nContent-Disposition: form-data; name=\"file\"; filename=\"u.jpg\"\r\nContent-Type: image/jpeg\r\n\r\n".data(using:.utf8)!)
  body.append(data);body.append("\r\n--\(b)--\r\n".data(using:.utf8)!)
  let(d,_)=try await URLSession.shared.upload(for:req,from:body)
  return d}
